function creditGuide11(r=Credit11.active(ten).rules,preview=false,versionId=Credit11.active(ten).id){const v=Credit11.active(ten);return `<div class="royalty107 guide-credit11"><header class="head107"><div><span class="eyebrow107">${T('STANDAR & PENANDA','STANDARDS & MARKERS')}</span><h1>${T('Penggunaan Kredit','Using Credits')}</h1><p>${T('Ketahui alokasi, pemakaian, dan masa berlaku kreditmu.','Understand allocation, usage and expiry of your credits.')}</p></div><span class="pill107">${preview?T('Pratinjau rancangan','Draft preview'):T('Aturan','Policy')+' '+versionId}</span></header><section class="panel107"><h2>${T('Satu lagu, sesuai layanan pilihanmu.','One track, your choice of service.')}</h2><div class="rates11">${Object.entries(r.cost).map(([k,n])=>`<article class="${k==='MAX'?'max11':''}"><small>Rilis Musik</small><h3>${k}</h3><strong>${n}<span> ${T('kredit / lagu','credits / track')}</span></strong></article>`).join('')}</div><p>${T('Single, EP, dan Album dihitung dari jumlah lagu, bukan jumlah kemasan rilisan.','Singles, EPs and albums are charged by track count, not release count.')}</p></section><section class="panel107"><h2>${T('Tiga sumber kredit','Three credit sources')}</h2><div class="table107"><table><thead><tr><th>${T('Jenis','Type')}</th><th>${T('Penggunaan dan masa berlaku','Usage and validity')}</th></tr></thead><tbody><tr><td>${T('Kredit harian','Daily credits')}</td><td>${r.daily} ${T('kredit pada setiap hari ketika akun dan paket memenuhi syarat. Diperbarui pukul 00.00 WIB; sisa hari sebelumnya tidak menumpuk. Perubahan jumlah berlaku pada jatah hari berikutnya.','credits per eligible day. Resets at 00:00 WIB; unused credits do not accumulate. Quantity changes apply to the next daily grant.')}</td></tr><tr><td>${T('Kredit tambahan','Additional credits')}</td><td>${T('Kredit pembelian tidak kedaluwarsa. Tetap tersedia setelah langganan berakhir, selama akun memenuhi syarat operasi.','Purchased credits never expire. They remain available after a subscription ends, subject to account eligibility.')}</td></tr><tr><td>${T('Kredit sementara','Temporary credits')}</td><td>${T('Memiliki tanggal kedaluwarsa. Pengembalian kredit harian yang telah kedaluwarsa berlaku','Has an expiry date. Returned expired daily credits remain valid for')} ${r.temporaryHours} ${T('jam. Periksa waktu yang tercantum pada kreditmu.','hours. Check the expiry shown on your credit balance.')}</td></tr></tbody></table></div><p>${T('Urutan penggunaan','Usage order')}: <strong>${priorityName11(r.priority)}</strong>.</p></section><section class="panel107"><h2>${T('Kapan kredit dihitung?','When are credits counted?')}</h2><div class="credit-steps11"><article><span>01</span><h3>${T('Draft','Draft')}</h3><p>${T('Belum mengalokasikan kredit.','No credits are allocated.')}</p></article><article><span>02</span><h3>${T('Diajukan','Submitted')}</h3><p>${T('Kredit disisihkan untuk lagu yang diajukan. Tidak lagi termasuk saldo tersedia.','Credits are reserved for submitted tracks and excluded from the available balance.')}</p></article><article><span>03</span><h3>${T('Tayang','Live')}</h3><p>${T('Kredit terpakai per lagu setelah petugas mengonfirmasi tayang. UPC atau ISRC saja tidak menyelesaikan pemakaian.','Credits are consumed per track after staff confirm it is live. UPC or ISRC alone does not settle credits.')}</p></article></div><p>${T('Contoh: EP 4 lagu dengan Standard membutuhkan','Example: a four-track Standard EP requires')} <strong>${4*r.cost.Standard} ${T('kredit','credits')}</strong>. ${T('Jika 3 lagu dikonfirmasi tayang,','If three tracks are confirmed live,')} ${3*r.cost.Standard} ${T('kredit terpakai dan','credits are consumed and')} ${r.cost.Standard} ${T('kredit masih dialokasikan untuk lagu terakhir.','credits remain allocated to the last track.')}</p></section><section class="panel107"><h2>${T('Pengembalian & bonus','Returns & bonuses')}</h2><ul class="guide-list11"><li>${T('Kredit pembelian kembali ke saldo tambahan tanpa kedaluwarsa saat alokasinya dilepas.','Purchased credits return without expiry when their allocation is released.')}</li><li>${T('Kredit harian yang masih berlaku kembali pada hari yang sama. Jika sudah kedaluwarsa, pengembaliannya menjadi kredit sementara.','Valid daily credits return to the same day. Once expired, they return as temporary credits.')}</li><li>${T('Kredit sementara yang masih berlaku kembali dengan tanggal kedaluwarsa semula. Jika kedaluwarsa selama dialokasikan, durasi pengembaliannya mengikuti sisa waktu ketika dialokasikan, dibatasi masa sementara pengajuan. Tidak otomatis mendapat masa baru penuh.','Valid temporary credits retain their expiry. If they expire while reserved, returned validity follows the remaining time at reservation, capped by the request’s temporary-credit policy, rather than a full new period.')}</li><li>${T('Permintaan perbaikan tidak langsung mengembalikan kredit. Alokasi diteruskan; perubahan jumlah lagu dihitung sebagai selisih.','Corrections do not immediately return credits. Allocation continues; track-count changes are settled as a difference.')}</li><li>${T('Bonus yang perlu diklaim memiliki batas','Claimable bonuses have a')} ${r.claimHours} ${T('jam sejak dikirim. Kredit sementara bonus berlaku','hour claim window after sending. Temporary bonus credits remain valid for')} ${r.temporaryHours} ${T('jam sejak klaim; kredit permanen tidak kedaluwarsa. Penawaran lama mempertahankan ketentuannya.','hours from claiming; permanent credits do not expire. Existing offers retain their terms.')}</li></ul><p class="note107">${T('Pengajuan berjalan memakai aturan saat diterima. Lihat rincian rilisan untuk jumlah serta alasan pengembalian. Pembayaran WAMI menggunakan rupiah atau benefit paket, bukan kredit rilisan.','Requests in progress retain the rules accepted at submission. Release details show return amounts and reasons. WAMI uses monetary payment or plan benefits, not release credits.')}</p></section></div>`}
function priorityName11(value){return T(...({expiry:['Masa berlaku paling dekat, lalu kredit tambahan','Earliest expiry, then additional credits'],daily:['Kredit harian, sementara, lalu tambahan','Daily, temporary, then additional credits'],temporary:['Kredit sementara, harian, lalu tambahan','Temporary, daily, then additional credits']})[value])}
function ruleInputs11(r){return `<div class="formgrid11">${[['daily','Kredit harian per hari','Daily credits per day',r.daily,0,100],['Standard','Standard · kredit per lagu','Standard · credits per track',r.cost.Standard,1,100],['Express','Express · kredit per lagu','Express · credits per track',r.cost.Express,1,100],['MAX','MAX · kredit per lagu','MAX · credits per track',r.cost.MAX,1,100],['temporaryHours','Masa kredit sementara · jam','Temporary validity · hours',r.temporaryHours,1,720],['claimHours','Batas klaim bonus · jam','Bonus claim window · hours',r.claimHours,1,720]].map(([k,a,b,n,min,max])=>`<label>${T(a,b)}<input type="number" name="${k}" min="${min}" max="${max}" step="1" value="${n}" required></label>`).join('')}<label>${T('Urutan penggunaan','Usage order')}<select name="priority">${['expiry','daily','temporary'].map(k=>`<option value="${k}" ${r.priority===k?'selected':''}>${priorityName11(k)}</option>`).join('')}</select></label></div>`}
function creditConfig11(){if(ten.role!=='super')return denied9();const c=Credit11.init(ten),active=Credit11.active(ten),r=c.draft?.rules||active.rules;return `<section class="panel107 policy11"><header class="head107"><div><span class="eyebrow107">${T('ATURAN PENGGUNAAN','USAGE RULES')}</span><h2>${T('Satu aturan untuk panduan dan perhitungan.','One policy for guidance and calculation.')}</h2><p>${T('Aturan berlaku','Active policy')} ${active.id} · ${c.draft?T('Ada rancangan tersimpan','Saved draft available'):T('Belum ada perubahan rancangan','No saved changes')}</p></div>${B11(T('Lihat panduan','View guide'),'guide','','text')}</header>${c.versions.filter(v=>v.effective>ten.now).map(v=>`<p class="note107">${T('Aturan terjadwal','Scheduled policy')} ${v.id} · ${date10(v.effective,true)} WIB</p>`).join('')}<form data-form11="credit-draft" data-version="${c.revision}">${ruleInputs11(r)}<p class="note107">${T('Kredit permanen tetap tanpa kedaluwarsa. Pengajuan dan bonus berjalan tidak berubah. Jatah harian hari ini tetap; jumlah baru mulai pada pemberian berikutnya.','Permanent credits keep no expiry. Existing requests and bonuses stay unchanged. Today’s daily grant stays intact; the next grant uses the new quantity.')}</p><p class="error11" role="alert"></p><footer class="actions107"><button class="btn" type="submit">${T('Simpan rancangan','Save draft')}</button>${c.draft?B11(T('Terapkan perubahan','Apply changes'),'publish-preview','','primary'):''}</footer></form><details class="section11"><summary>${T('Riwayat penerapan','Publication history')}</summary>${c.history.map(v=>`<p><strong>${T('Aturan','Policy')} ${v.id}</strong> · ${date10(v.at,true)} WIB · ${E(v.actor)}<br>${T('Berlaku','Effective')}: ${date10(v.effective,true)} WIB<br>${v.rules.daily} ${T('kredit harian','daily credits')} · Standard ${v.rules.cost.Standard} / Express ${v.rules.cost.Express} / MAX ${v.rules.cost.MAX}<br>${T('Kredit sementara','Temporary credits')}: ${v.rules.temporaryHours} ${T('jam','hours')} · ${T('Batas klaim','Claim window')}: ${v.rules.claimHours} ${T('jam','hours')}<br>${priorityName11(v.rules.priority)}</p>`).join('')||'<p>—</p>'}</details></section>`}
function publishPreview11(){if(ten.role!=='super')return;const c=Credit11.init(ten);if(!c.draft)return;const a=Credit11.active(ten).rules,b=c.draft.rules;const rows=[['Kredit harian',a.daily,b.daily],...Object.keys(a.cost).map(k=>[k,a.cost[k],b.cost[k]]),['Masa sementara (jam)',a.temporaryHours,b.temporaryHours],['Batas klaim (jam)',a.claimHours,b.claimHours],['Urutan pemakaian',priorityName11(a.priority),priorityName11(b.priority)]];reviewDialogUI(T('Tinjau penerapan aturan','Review policy publication'),`<form data-form11="credit-publish" data-version="${c.revision}" class="wizard11"><h2>${T('Perubahan yang akan berlaku','Changes to publish')}</h2><div class="table107"><table><thead><tr><th>${T('Aturan','Rule')}</th><th>${T('Sekarang','Current')}</th><th>${T('Rancangan','Draft')}</th></tr></thead><tbody>${rows.map(([k,x,y])=>`<tr><td>${k}</td><td>${E(x)}</td><td><strong>${E(y)}</strong></td></tr>`).join('')}</tbody></table></div><label>${T('Waktu berlaku','Effective time')}<select name="when"><option value="now">${T('Setelah diterapkan','On publication')}</option><option value="scheduled">${T('Jadwalkan','Schedule')}</option></select></label><label>${T('Tanggal terjadwal · WIB (jika dipilih)','Scheduled date · WIB (if selected)')}<input type="datetime-local" name="effective"></label><p>${T('Pengajuan berjalan, saldo permanen, masa kredit yang telah diterbitkan, dan bonus yang sudah dikirim tetap memakai ketentuan sebelumnya.','Existing requests, permanent balances, issued credit expiry and sent bonuses keep their previous terms.')}</p><details><summary>${T('Pratinjau panduan pengguna','Preview user guide')}</summary>${creditGuide11(b,true)}</details><label class="check11"><input name="checked" type="checkbox" required>${T('Saya sudah memeriksa dampak perubahan ini.','I have reviewed the impact of these changes.')}</label><p class="error11" role="alert"></p><footer class="actions107">${B11(T('Kembali','Back'),'close','','text')}<button class="btn primary" type="submit">${T('Terapkan perubahan','Apply changes')}</button></footer></form>`)}
function wamiPolicy11(){if(ten.role!=='super')return '';const m=Wami11.init(ten),cfg=settings11();return `<section class="panel107 policy11" id="wami-policy11"><span class="eyebrow107">WAMI</span><h2>${T('Prosedur & Pengingat WAMI','WAMI Procedures & Reminders')}</h2><p>${T('Jam kerja mengikuti pengaturan operasional','Working hours follow operational settings')}: ${E(data.policy.start)}–${E(data.policy.end)} WIB. ${T('Hari libur dikecualikan. Waktu menunggu WAMI bukan keterlambatan kerja petugas.','Holidays are excluded. Waiting for WAMI is separate from staff handling time.')}</p><form data-form11="wami-policy" data-version="${m.version}"><div class="formgrid11">${Object.entries({queueWarn:'Antrean · pengingat (jam kerja)',queueDue:'Antrean · atensi (jam kerja)',workWarn:'Penanganan · pengingat (jam kerja)',workDue:'Penanganan · atensi (jam kerja)',labelWarn:'Perbaikan label · pengingat awal (jam)',labelSecond:'Perbaikan label · pengingat kedua (jam)',labelDue:'Perbaikan tertunda (jam)',externalDays:'Tindak lanjut WAMI (hari kerja)'}).map(([k,label])=>`<label>${label}<input type="number" min="1" max="720" step="1" name="${k}" value="${m.policy[k]}" required></label>`).join('')}</div><p>${T('Berlaku untuk pengajuan baru. Membuka halaman atau mencatat kendala tidak menghapus keterlambatan.','Applies to new requests. Opening a page or recording an obstacle does not erase lateness.')}</p><p class="error11" role="alert"></p><button class="btn primary" type="submit">${T('Simpan pengingat WAMI','Save WAMI reminders')}</button></form><details class="section11"><summary>${T('Riwayat perubahan','Change history')}</summary>${m.policyHistory.map(h=>`<p>${date10(h.at,true)} WIB · ${E(h.actor)}</p>`).join('')||'—'}</details></section>`}
function wamiBenefits11(){if(ten.role!=='super')return '';const cfg=settings11();return `<section class="panel107"><h2>${T('Layanan WAMI','WAMI Service')}</h2><p>${T('Harga dan benefit ini menjadi acuan pengajuan WAMI baru. Tidak menggunakan kredit rilisan.','This price and benefit policy applies to new WAMI requests. It does not use release credits.')}</p><form data-form11="wami-benefit" data-version="${cfg.version}"><label>${T('Biaya per lagu · Rp','Fee per track · IDR')}<input name="price" type="number" min="1" max="10000000" value="${cfg.price}" required></label><fieldset><legend>${T('Paket yang mencakup pendaftaran','Plans including registration')}</legend>${catalogue104().plans.map(p=>`<label class="check11"><input type="checkbox" name="included" value="${E(p.id)}" ${cfg.included.includes(p.id)?'checked':''}>${E(p.name)}</label>`).join('')}</fieldset><p class="error11" role="alert"></p><button type="submit" class="btn primary">${T('Simpan ketentuan WAMI','Save WAMI terms')}</button></form><details class="section11"><summary>${T('Riwayat ketentuan','Terms history')}</summary>${cfg.history.map(h=>`<p>${date10(h.at,true)} WIB · ${E(h.actor)} · ${money10(h.price)} · ${T('Termasuk','Included')}: ${E(h.included.join(', ')||'—')}</p>`).join('')||'—'}</details></section>`}
